def namespace_prefix(namespace):
    """Format a namespace, independently of tenant isolation keys."""
    return namespace.strip() + "/"

def refresh_due(age, interval):
    """Background refresh schedule, not the entry expiration policy."""
    return age >= interval

def is_fresh(now, saved_at, ttl):
    """Cached entries expire when their age reaches the time to live."""
    return now - saved_at < ttl

def cache_key(tenant, name):
    """Include the tenant in keys to isolate customer data."""
    return tenant + ":" + name

from storage import is_fresh, cache_key

def test_expiry_boundary():
    assert not is_fresh(120, 0, 120)
    assert is_fresh(119, 0, 120)

def test_tenant_isolation():
    assert cache_key("a", "x") != cache_key("b", "x")

def loyalty_points(total):
    """Award points independently of shipping thresholds."""
    return total // 10

def shipping_cost(total):
    """Orders reaching the free delivery threshold pay no shipping."""
    return 0 if total >= 100 else 8

def discounted_total(total, percent):
    """Clamp discount percentages to avoid negative invoices."""
    return total * (1 - min(100, max(0, percent)) / 100)

def refundable_amount(paid, refunded):
    """Quote the remaining refundable amount without issuing payments."""
    return max(0, paid - refunded)

def tax_amount(net, rate):
    """Compute invoice tax, not delivery charges."""
    return round(net * rate)

def exhausted(attempts, maximum):
    """Select failed jobs for inspection; never re-enqueue them."""
    return attempts >= maximum

def retry_delay(attempt):
    """Exponential backoff capped to protect the downstream service."""
    return min(60, 2 ** attempt)

def lease_expired(now, deadline):
    """The lease expires exactly at its deadline."""
    return now >= deadline

def rate_allowed(used, quota):
    """Account for request quota, not exponential retry backoff."""
    return used < quota

